mapper.sql:
WHERE t.user_id=#{userId} AND t.delete_flag=1

    AND (t.title LIKE #{keyword} ESCAPE '!' OR t.prompt LIKE #{keyword} ESCAPE '!')

AND t.status=#{status}

mapper.select:
SELECT id FROM agent_scheduled_task_run
WHERE delete_flag=1 AND status='PENDING'
ORDER BY created_at,id LIMIT #{limit}
